(function () {
'use strict';
function boot() {
var U = window.U;
var Tools = window.Tools || {};
var Result = window.ToolCore && window.ToolCore.Result;
var RV = window.ToolCore && window.ToolCore.ResultView;
var form = document.getElementById('taxForm');
if (!form || !U || !Tools.tax || !Result || !RV) return;
var $ = function (id) { return document.getElementById(id); };
var deductionFields = {
childEducation: 'tax-childEducation',
infantCare: 'tax-infantCare',
continuingEducation: 'tax-continuingEducation',
vocationalEducationAnnual: 'tax-vocationalEducationAnnual',
mortgageInterest: 'tax-mortgageInterest',
housingRent: 'tax-housingRent',
elderlySupport: 'tax-elderlySupport',
medicalAnnualExpense: 'tax-medicalAnnualExpense',
};
function readInput() {
var deductions = {};
Object.keys(deductionFields).forEach(function (key) {
deductions[key] = $(deductionFields[key]).value;
});
return {
salary: $('tax-salary').value,
insurance: $('tax-insurance').value,
threshold: $('tax-threshold').value,
bonus: $('tax-bonus').value,
bonusMode: $('tax-bonusMode').value,
policyYear: $('tax-policyYear').value,
deductions: deductions,
};
}
form.addEventListener('submit', function (event) {
event.preventDefault();
var input = readInput();
var result = Tools.tax.calculate(input);
RV.renderError($('tax-error'), result);
if (result.status !== 'success') {
$('tax-result').hidden = true;
$('tax-explain').hidden = true;
return;
}
var details = result.details.slice();
if (result.metrics.bonus > 0) {
var alternateMode = input.bonusMode === 'combined' ? 'separate' : 'combined';
var alternate = Tools.tax.calculate(Object.assign({}, input, { bonusMode: alternateMode }));
if (alternate.status === 'success') {
details.push(Result.detail('另一种计税方式税额', alternate.metrics.tax, alternateMode === 'combined' ? '并入当月工资' : '单独计税'));
}
}
$('tax-afterTax').textContent = U.money(result.metrics.afterTax);
$('tax-tax').textContent = U.money(result.metrics.tax);
RV.renderDetails($('tax-detail'), details);
RV.renderExplanation($('tax-explain'), result);
$('tax-explain').hidden = false;
$('tax-result').hidden = false;
U.track('calc_result', { tool: 'tax', mode: input.bonusMode, success: true });
});
$('tax-clear').addEventListener('click', function () {
form.reset();
$('tax-threshold').value = 5000;
$('tax-bonus').value = 0;
$('tax-result').hidden = true;
$('tax-explain').hidden = true;
$('tax-error').hidden = true;
RV.clear($('tax-detail'));
RV.clear($('tax-explain'));
});
}
if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
else boot();
})();
